import json
from dataclasses import dataclass, field


@dataclass
class Account:
    """A ledger account with a running balance and an audit trail."""
    name: str
    balance: float = 0.0
    history: list = field(default_factory=list)

    def deposit(self, amount, memo=""):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self.balance += amount
        self.history.append({"op": "deposit", "amount": amount, "memo": memo, "balance": self.balance})
        return self.balance

    def withdraw(self, amount, memo=""):
        if amount <= 0:
            raise ValueError("withdraw must be positive")
        if amount > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amount
        self.history.append({"op": "withdraw", "amount": amount, "memo": memo, "balance": self.balance})
        return self.balance

    def transfer(self, other, amount, memo=""):
        if amount <= 0:
            raise ValueError("transfer must be positive")
        if amount > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amount
        self.history.append({"op": "transfer_out", "amount": amount, "memo": memo, "balance": self.balance})
        other.balance += amount
        other.history.append({"op": "transfer_in", "amount": amount, "memo": memo, "balance": other.balance})
        return self.balance

    def statement(self):
        lines = [f"Account: {self.name}"]
        for h in self.history:
            lines.append(f"  {h['op']:<9} {h['amount']:>10.2f}  -> {h['balance']:>10.2f}  {h['memo']}")
        lines.append(f"  {'final':<9} {'':>10}     {self.balance:>10.2f}")
        return "\n".join(lines)

    def to_json(self):
        return json.dumps({"name": self.name, "balance": self.balance, "history": self.history}, indent=2)
